"""Template rendering for dictionary lookup results without using an LLM."""

from __future__ import annotations

from collections import defaultdict
from typing import List, Optional, Sequence, Tuple

SenseRow = Tuple[str, str, str, Optional[str], int, int]
# (headword, pos, gloss, example, freq, idx)

NO_TERM_MESSAGE = "I couldn't find a word to look up in that."


def render_not_found(
    term: str,
    suggestions: Optional[Sequence[str]] = None,
) -> str:
    """Render a deterministic not-found message generated by code, including closest word suggestions."""
    msg = f"No definition found for '{term}'."
    if suggestions:
        if len(suggestions) == 1:
            msg += f" Did you mean '{suggestions[0]}'?"
        else:
            sugg_list = ", ".join(f"'{s}'" for s in suggestions)
            msg += f" Did you mean: {sugg_list}?"
    return msg


def render_no_term() -> str:
    """Render message when no term could be extracted from the user query."""
    return NO_TERM_MESSAGE


def render_definition(
    rows: Sequence[SenseRow],
    max_senses_per_group: int = 3,
) -> str:
    """Render senses grouped by headword and part-of-speech.

    Shows up to `max_senses_per_group` senses per (headword, pos),
    each with its gloss and optional example.
    """
    if not rows:
        return "No definition found."

    # Group by headword -> pos -> list of senses
    grouped: dict[str, dict[str, list[tuple[str, Optional[str]]]]] = defaultdict(
        lambda: defaultdict(list)
    )

    for headword, pos, gloss, example, _freq, _idx in rows:
        grouped[headword][pos].append((gloss, example))

    lines: List[str] = []
    for headword, pos_map in grouped.items():
        lines.append(headword)
        for pos, senses in pos_map.items():
            for gloss, example in senses[:max_senses_per_group]:
                lines.append(f"  ({pos}) {gloss}")
                if example:
                    lines.append(f'    e.g. "{example}"')

    return "\n".join(lines)


def render_closest_definition(
    original_term: str,
    closest_term: str,
    rows: Sequence[SenseRow],
    other_suggestions: Optional[Sequence[str]] = None,
    max_senses_per_group: int = 3,
) -> str:
    """Render definition of the closest matching word along with additional suggestions."""
    lines: List[str] = [
        f"No exact match found for '{original_term}'. Showing definition for closest match '{closest_term}':\n"
    ]
    lines.append(render_definition(rows, max_senses_per_group=max_senses_per_group))
    if other_suggestions:
        sugg_list = ", ".join(f"'{s}'" for s in other_suggestions)
        lines.append(f"\nOther suggestions: {sugg_list}")
    return "\n".join(lines)


def render_fuzzy_definition(
    term: str,
    headword: str,
    rows: Sequence[SenseRow],
    max_senses_per_group: int = 3,
) -> str:
    """Render definition for a fuzzy match with header 'Showing results for <headword> (you typed <term>)'."""
    header = f"Showing results for {headword} (you typed {term})\n"
    return header + render_definition(rows, max_senses_per_group=max_senses_per_group)

